-- Generated by Loom
-- Generator: satellite
-- Variant: multi_active
-- Hash function: sha256
{{ config(materialized='incremental', incremental_strategy='append') }}
WITH staged AS (
    SELECT
        LOWER(sha256(UPPER(TRIM(CAST(s.customer_id AS VARCHAR))))) AS customer_hk,
        LOWER(sha256(concat(COALESCE(CAST(s.phone_number AS VARCHAR), '~')))) AS __hash_diff,
        s.phone_type AS phone_type,
        s.phone_number,
        localtimestamp AS __loaded_at,
        'crm' AS __record_source
    FROM {{ ref('stg_customer_phones') }} AS s
    JOIN {{ ref('hub_customer') }} AS p
        ON LOWER(sha256(UPPER(TRIM(CAST(s.customer_id AS VARCHAR))))) = p.customer_hk
)
{% if is_incremental() %}
, latest AS (
    SELECT customer_hk, phone_type, __hash_diff
    FROM (
        SELECT
            customer_hk,
            phone_type,
            __hash_diff,
            ROW_NUMBER() OVER (
                PARTITION BY customer_hk, phone_type
                ORDER BY __loaded_at DESC, __hash_diff DESC
            ) AS rn
        FROM {{ this }}
    ) AS ranked
    WHERE rn = 1
)
{% endif %}
SELECT
    st.customer_hk,
    st.__hash_diff,
    st.phone_type,
    st.phone_number,
    st.__loaded_at,
    st.__record_source
FROM staged AS st
{% if is_incremental() %}
LEFT JOIN latest AS l
    ON st.customer_hk = l.customer_hk
    AND st.phone_type = l.phone_type
WHERE l.customer_hk IS NULL
    OR st.__hash_diff <> l.__hash_diff
{% endif %}
